body.ST:
FUNCTION_BLOCK TP_RET
VAR_INPUT
    IN :            BOOL ;              (* Input *)
    RESET :	    BOOL ;		(*Reset*)	
    PT :            TIME ;              (* Pulse Time *)
END_VAR
VAR_OUTPUT
    Q :             BOOL ;              (* Output Pulse *)
    ET :            TIME ;              (* Elapsed Time *)
END_VAR
VAR
    M :             BOOL ;              (* State *)
    T0 :            DT ;                (* Start Time *)
END_VAR

(*
 *=F==========================================================================
 * FUNCTION_BLOCK:  TP_RET
 * Purpose:         Pulse.
 * Remarks:
 * Replaces "Timers with constant timer value: pulse retriggerable" in Honeywell system.
 *
 *=F==========================================================================
 *)

    (* Body *)


		IF IN AND NOT M AND NOT RESET THEN
			Q := TRUE ;
			T0 := GetTimer() ;
			ET := T#0ms ;

		END_IF ;

		IF Q THEN
			ET := GetTimer() - T0 ;
		END_IF ;


		IF ET >= PT THEN
			ET := PT ;
			Q := FALSE ;

		END_IF ;

		IF RESET THEN
		Q := FALSE ;
		ET := T#0ms ;
		END_IF ;

	M := IN ;

END_FUNCTION_BLOCK
